import { git } from './git.ts'

import type { GeneratedReason } from './types.ts'

/**
 * Names which are generated by a dependency manager, not merely anything that
 * happens to end in `.lock` — the latter catches ordinary source files too.
 */
const LOCKFILES = new Set([
  'bun.lock',
  'bun.lockb',
  'Cargo.lock',
  'composer.lock',
  'Gemfile.lock',
  'mix.lock',
  'npm-shrinkwrap.json',
  'package-lock.json',
  'Pipfile.lock',
  'pnpm-lock.yaml',
  'poetry.lock',
  'uv.lock',
  'yarn.lock',
])

/** Keep each invocation comfortably below the platform's argument limit. */
const ATTRIBUTE_BATCH_SIZE = 512

/**
 * The built-in, deliberately small path heuristic.
 *
 * Reimplementing GitHub Linguist here would bring a large and moving policy
 * into a dependency-free server. Repositories can state anything beyond these
 * common cases explicitly with `linguist-generated` in `.gitattributes`.
 */
export function generatedReasonForPath(path: string): GeneratedReason | null {
  const parts = path.split('/')
  const name = parts.at(-1) ?? path

  if (LOCKFILES.has(name)) return 'lockfile'
  if (parts.includes('__snapshots__') || name.endsWith('.snap')) return 'snapshot'
  if (parts.slice(0, -1).includes('dist')) return 'distribution'
  return null
}

/** What the boolean-shaped Linguist attribute says, if it says anything. */
function asBooleanAttribute(value: string): boolean | null {
  if (value === 'set' || value === 'true') return true
  if (value === 'unset' || value === 'false') return false
  return null
}

/**
 * Read one attribute for every path, from the version of `.gitattributes` that
 * belongs to the code under review.
 *
 * `-z` makes the triplets safe for spaces, newlines and colons in file names.
 * Paths ride in argv rather than being interpolated into a shell, and `--`
 * keeps even a leading dash literal. Batches bound argv without paying for one
 * git process per file.
 */
async function generatedAttributes(
  repoPath: string,
  paths: string[],
  source: string | null,
): Promise<Map<string, boolean | null>> {
  const batches: string[][] = []
  for (let i = 0; i < paths.length; i += ATTRIBUTE_BATCH_SIZE) {
    batches.push(paths.slice(i, i + ATTRIBUTE_BATCH_SIZE))
  }

  const outputs = await Promise.all(
    batches.map((batch) =>
      git(repoPath, [
        'check-attr',
        '-z',
        ...(source ? [`--source=${source}`] : []),
        'linguist-generated',
        '--',
        ...batch,
      ]),
    ),
  )

  const attributes = new Map<string, boolean | null>()
  for (const output of outputs) {
    const fields = output.split('\0')
    for (let i = 0; i + 2 < fields.length; i += 3) {
      const path = fields[i]
      const attribute = fields[i + 1]
      const value = fields[i + 2]
      if (path && attribute === 'linguist-generated' && value) {
        attributes.set(path, asBooleanAttribute(value))
      }
    }
  }
  return attributes
}

/**
 * path -> why it is generated. Absence means ordinary reviewable source.
 *
 * An explicit false attribute is load-bearing: it lets a repository keep, for
 * example, a hand-maintained file under `dist/` visible despite the heuristic.
 */
export async function classifyGeneratedFiles(
  repoPath: string,
  paths: string[],
  { source = null }: { source?: string | null } = {},
): Promise<Map<string, GeneratedReason>> {
  const unique = [...new Set(paths)]
  if (unique.length === 0) return new Map()

  const attributes = await generatedAttributes(repoPath, unique, source)
  const generated = new Map<string, GeneratedReason>()
  for (const path of unique) {
    const attribute = attributes.get(path)
    if (attribute === true) generated.set(path, 'gitattributes')
    else if (attribute !== false) {
      const reason = generatedReasonForPath(path)
      if (reason) generated.set(path, reason)
    }
  }
  return generated
}
